/* LEFT ACTION TAB STYLE - BEGIN */
/* Color Variables */
#evo_left_action {
    display:block;
    position: fixed;
    top: 240px;
    left: 0;
    bottom: 0;
    width: 1px;
    z-index: 1;
}
#evo_left_action ul {
    list-style: none;
    padding: 0;
}
body #evo_left_action li {
    display: block;
    width: 280px;
    transition: background-color 0.3s, margin 0.8s;
    min-height: 50px;
    color: #fff;
    background-color: #0B76A3;
    margin-bottom: 10px;
    padding-top: 0px;
    margin-left: -213px;
    cursor: pointer;
    border-radius: 0 6px 6px 0;
}
#evo_left_action li:hover {
    margin-left: 0px;
    box-shadow: 0 0 2px 0 1px 5px rgba(104, 104, 104, 0.8);
}
#evo_left_action li:hover i {
    /* color: rgba(19, 137, 97, 1.0) */
    color: #fff;
}
#evo_left_action a {
    display: inline-block;
    text-align: right;
    color: #fff;
    padding: 15px 5px;
    font-size: 15px;
    font-weight: 400;
    line-height: 24px;
    transition: all 0.3s;
    z-index: 15;
    text-transform: uppercase;
    text-decoration: none;
    width: 100%;
    position: relative;
    padding-right: 70px;
    padding-top: 17px;
}
#evo_left_action a .label_text {
    width: 100%;
    text-align: right;
    display: inline-block;
    transform: translateX(-60px);
}
#evo_left_action a:hover {
    /*background-color: rgba(40, 40, 40, 1.0);*/
}
#evo_left_action i {
    display: inline-block;
    font-size: 38px;
    color: #fff;
    position: absolute;
    right: 10px;
    top: 7px;

}
@media (max-width: 1080px) {#evo_left_action {display:none;}}
@media (max-width: 768px) {
    /* left action */
    #evo_left_action {
        position: relative;
        top: 0px;
        left: 0px;
        width: 100%;
        padding-top: 20px;
    }
    #evo_left_action li:first-child {margin-top: 10px;}
    #evo_left_action li {
        width: 90% !important;
        margin-left: 5% !important;
    }
    #evo_left_action a .label_text, #evo_left_action span .label_text {text-align: center;}
    #evo_left_action a .label_text, #evo_left_action span .label_text {transform: unset !important;}

}
/* LEFT ACTION TAB STYLE - END */

